  ('zcrm_5797994000003776445', 'Claim Health', 'Claim Health', 'Zachary Christinat', 'Kevin Calcado', 'Developer of automated billing tools designed for use in post-acute healthcare settings. The company''s platform generates compliant claim submissions, creates appeal letters for denied claims, integrates real-time financial reporting, and supports end-to-end revenue cycle processes, enabling home healthcare providers and administrative teams to reduce manual billing tasks, improve reimbursement accuracy, maintain regulatory compliance, and optimize financial performance through streamlined claims management and automated documentation workflows.', 'HV STEM', 'Healthcare', 'Spring 2026', 'PitchBook', 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-03-03 10:03:12', '2026-03-03 10:03:12', NULL),
  ('zcrm_5797994000003776495', 'Double Blind Bio', 'Double Blind BIo', 'Zachary Christinat', 'David Hughes', 'Developer of AI (artificial intelligence) agents designed to automate administrative work in clinical trial operations and support more autonomous trials. The company offers intelligent software that connects trial sites, sponsors, and data, enabling clinical research teams to focus on patients and science and move therapeutics from development to availability faster.', 'HV STEM', 'Healthcare', 'Spring 2026', 'PitchBook', 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-03-03 10:21:16', '2026-03-03 10:21:16', NULL),
  ('zcrm_5797994000003776522', 'SynthioLabs', 'SynthioLabs', 'Zachary Christinat', 'Supreet Deshpande', 'Developer of clinical-grade voice and artificial intelligence platforms designed to improve pharmaceutical customer engagement through real-time access to compliant, evidence-based information. The company offers voice and multimodal agents that support field teams, healthcare professionals, and patients, enabling pharmaceutical organizations to enhance engagement quality, strengthen operational efficiency, and achieve clearer commercial outcomes.', 'HV STEM', 'Healthcare', 'Spring 2026', 'PitchBook', 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-03-03 10:25:08', '2026-03-03 10:25:08', NULL),
  ('zcrm_5797994000003776549', 'PodPlay', 'PodPlay', 'Mia Dansby', 'Maximilian Kogler', 'Operator of a digital management system for recreational and sports facilities designed for organizing, scheduling, and maintaining venue operations. The company''s platform includes automated court reservations, membership and event management, video replay and digital scoreboard integration, branding customization, and data analytics, enabling sports clubs and facility managers to streamline operations, extend accessibility, and optimize court utilization efficiently.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'mia dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-03-03 11:11:12', '2026-03-03 11:11:12', '2026-03-03 11:11:12'),
  ('zcrm_5797994000003776584', 'Level Up Basketball', 'Level Up Basketball', 'Mia Dansby', 'Anton Zimin', 'Developer of a basketball training mobile social app designed for the skills training community of basketball players and coaches. The company''s app offers camera support, club management tools, community, performance tracking, training plans, and web3 gamification, enabling users to track progress and leaderboards.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'mia dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-03-03 11:13:29', '2026-03-03 11:13:29', '2026-03-03 11:13:29'),
  ('zcrm_5797994000003776619', 'ScoutSync', 'ScoutSync', 'Mia Dansby', 'Darius Willis', 'Operator of a unified operating system for sports organizations intended to replace disconnected tools and manual workflows with a single platform. The company offers verified athlete data, technology-driven insights, and end-to-end team management tools, enabling teams across all levels of sport to streamline operations, improve recruitment processes, and strengthen decision-making.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Mia Dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-03-03 11:15:42', '2026-03-03 11:15:42', '2026-03-03 11:15:42'),
